<script setup lang="ts">
import {ref,computed,onMounted,watch,onBeforeUnmount} from 'vue'
import {RouterLink,useRouter} from 'vue-router'
import {api,write,ApiError,type Staff,type Page,type CatalogEvent,type Detail} from '../api'
import {pending,busy,commandMessage} from '../commands'
import {admission,retryAdmission,recoverAdmission,validateStaffTicket,type StaffTicket} from '../tickets'
import {uuidPattern} from '../customerCommands'
import TicketScanner from '../components/TicketScanner.vue'
import AdmissionWindowPanel from '../components/AdmissionWindowPanel.vue'
import {type WindowStatus,windowPath,readWindow} from '../admissionWindows'
const router=useRouter(),staff=ref<Staff|null>(null),sessionId=ref(''),code=ref(''),selected=ref<StaffTicket|null>(null),list=ref<Page<StaffTicket>|null>(null),audit=ref<Page<{requestId:string;action:string;reason:string|null;state:string}>|null>(null),enabled=ref(false),loading=ref(false),error=ref(''),reason=ref('LOST_CODE'),page=ref(1),inspected=ref<{id:string;code:string}|null>(null),events=ref<Page<CatalogEvent>|null>(null),eventId=ref(''),eventPage=ref(1),eventDetail=ref<Detail|null>(null)
const windowStatus=ref<WindowStatus|null>(null),windowLoaded=ref(0),tick=ref(performance.now())
const clock=setInterval(()=>tick.value=performance.now(),500);onBeforeUnmount(()=>clearInterval(clock))
function windowChanged(s:WindowStatus|null){windowStatus.value=s;windowLoaded.value=performance.now()}
const windowOpen=computed(()=>{const w=windowStatus.value;if(!w||w.sessionId!==sessionId.value||!w.opensAt||!w.closesAt)return false;const now=Date.parse(w.observedAt)+Math.max(0,tick.value-windowLoaded.value);return Date.parse(w.opensAt)<=now&&now<Date.parse(w.closesAt)})
const canStop=ref(false),confirmStop=ref(false)
watch(()=>pending.value,()=>{canStop.value=false;confirmStop.value=false})
const ownedPending=computed(()=>pending.value?.path.startsWith('/admin/admissions/')&&!windowPath.test(pending.value.path)&&pending.value.owner===staff.value?.username)
const blocked=computed(()=>loading.value||busy.value||!!pending.value||!staff.value?.canWrite)
function clearInspection(){selected.value=null;inspected.value=null;audit.value=null}
function scanned(value:string){if(blocked.value||!uuidPattern.test(sessionId.value))return;code.value=value;clearInspection();error.value=''}
watch(sessionId,value=>{windowChanged(null);code.value='';inspected.value=null;if(selected.value?.sessionId!==value)clearInspection()})
function state(s:string){return s==='ACTIVE'?'尚未使用':s==='CHECKED_IN'?'已驗票入場':'已撤銷'}
async function loadEvents(){events.value=await api(`/admin/events?page=${eventPage.value}&size=20`)}
async function selectEvent(){sessionId.value='';selected.value=null;inspected.value=null;list.value=null;eventDetail.value=null;error.value='';try{eventDetail.value=await api(`/admin/events/${eventId.value}`)}catch(e){error.value=(e as Error).message}}
async function load(){if(!staff.value||!uuidPattern.test(sessionId.value))return;loading.value=true;error.value='';try{list.value=await api(`/admin/admissions/tickets?sessionId=${sessionId.value}&page=${page.value}`);selected.value=null;inspected.value=null;audit.value=null}catch(e){error.value=(e as Error).message}finally{loading.value=false}}
async function inspect(){if(!staff.value)return;error.value='';loading.value=true;selected.value=null;try{selected.value=validateStaffTicket(await write<StaffTicket>('/admin/admissions/inspect','POST',{code:code.value.trim(),expectedSessionId:sessionId.value},staff.value.username));inspected.value={id:selected.value.id,code:code.value.trim()};windowChanged(await readWindow(sessionId.value));await readAudit()}catch(e){error.value=(e as Error).message}finally{loading.value=false}}
async function readAudit(){if(selected.value)audit.value=await api(`/admin/admissions/tickets/${selected.value.id}/audit`)}
async function perform(action:string){if(!staff.value||!selected.value)return;error.value='';try{const t=selected.value,r=await admission(staff.value,action==='CHECK_IN'?'/admin/admissions/check-ins':'/admin/admissions/revocations',{...(action==='CHECK_IN'?{code:code.value.trim()}:{ticketId:t.id,reason:reason.value}),expectedSessionId:t.sessionId,expectedVersion:t.version},t.id);selected.value=r.ticket;code.value='';await readAudit()}catch(e){error.value=(e as Error).message}}
async function retry(){if(!staff.value)return;try{selected.value=(await retryAdmission(staff.value)).ticket;sessionId.value=selected.value.sessionId;code.value='';await readAudit()}catch(e){error.value=(e as Error).message}}
async function lookup(stop=false){if(!staff.value)return;error.value='';try{const r=await recoverAdmission(staff.value,stop);canStop.value=r.state==='UNKNOWN';confirmStop.value=false;if(r.receipt){selected.value=r.receipt.ticket;sessionId.value=selected.value.sessionId;await readAudit()}if(r.state!=='UNKNOWN')code.value=''}catch(e){error.value=(e as Error).message}}
onMounted(async()=>{try{staff.value=await api('/auth/me');enabled.value=(await api<{enabled:boolean}>('/admin/admissions/settings')).enabled;await loadEvents()}catch(e){error.value=(e as Error).message;if(e instanceof ApiError&&e.status===401)await router.replace('/staff/login')}})
</script>
<template><section v-if="staff" class="content detail-page"><RouterLink to="/staff" class="back-link">← 活動管理</RouterLink><div class="eyebrow">TICKET ADMISSION</div><h1>票券核對與驗票</h1><p>{{staff.username}} · {{staff.canWrite?'管理員':'唯讀員工'}}</p><p>先確認入場場次。已使用或撤銷的票券不能再次入場；撤銷不代表退款。</p><div v-if="pending" class="notice warning" role="status"><p>有原員工操作尚未確認，其他寫入暫停。</p><button v-if="ownedPending" :disabled="busy||!staff.canWrite" @click="lookup()">核對原票券操作</button><p v-else-if="windowPath.test(pending.path)">請在下方入場時間窗核對原操作。</p><RouterLink v-else to="/staff">前往原操作頁面</RouterLink><template v-if="ownedPending&&staff.canWrite&&canStop"><button :disabled="busy" @click="retry">重試原票券操作</button><button :disabled="busy" @click="confirmStop=true">停止原票券請求</button><div v-if="confirmStop"><p>停止後，原請求不會再套用；若已成功，會顯示原結果。不撤回已入場或已撤銷的票券。</p><button :disabled="busy" @click="lookup(true)">確認永久停止原票券請求</button><button :disabled="busy" @click="confirmStop=false">返回核對</button></div></template></div><p v-if="commandMessage" class="notice" role="status">{{commandMessage}}</p><p v-if="error" class="notice error" role="alert">{{error}}</p><form class="panel" @submit.prevent="page=1;load()"><label>入場活動<select v-model="eventId" :disabled="loading||busy" required @change="selectEvent"><option value="" disabled>選擇活動</option><option v-for="e in events?.items" :key="e.id" :value="e.id">{{e.title}}</option></select></label><div v-if="events" class="pagination"><button type="button" :disabled="eventPage===1||loading||busy" @click="eventPage--;loadEvents()">上一批活動</button><span>{{eventPage}}</span><button type="button" :disabled="eventPage*events.size>=events.total||loading||busy" @click="eventPage++;loadEvents()">下一批活動</button></div><label>入場場次<select v-model="sessionId" required :disabled="loading||busy" @change="selected=null;inspected=null;list=null"><option value="" disabled>選擇場次</option><option v-for="s in eventDetail?.sessions" :key="s.id" :value="s.id">{{s.name}}</option></select></label><button :disabled="loading||busy||!uuidPattern.test(sessionId)">讀取場次票券</button></form><AdmissionWindowPanel :staff="staff" :session-id="sessionId" :disabled="loading" @changed="windowChanged"/><form v-if="staff.canWrite" class="panel" @submit.prevent="inspect"><TicketScanner v-if="uuidPattern.test(sessionId)" :key="sessionId" :disabled="blocked" @decoded="scanned" @reset="code='';clearInspection()"/><label>票券碼<textarea v-model="code" autocomplete="off" :disabled="blocked" required @input="clearInspection" /></label><button :disabled="blocked||!uuidPattern.test(sessionId)">核對票券</button></form><article v-if="selected" class="panel"><h2>{{selected.eventTitle}} · {{selected.sessionName}}</h2><p>{{selected.ticketName}} · 第 {{selected.unit}} 張 · {{state(selected.state)}}</p><p v-if="selected.state==='ACTIVE'&&!selected.eligible" class="notice warning">付款或帳號需要核對，暫停入場；仍可明確撤銷未使用票券。</p><p v-if="!enabled">驗票與撤銷寫入尚未開放。</p><p v-if="selected.state==='ACTIVE'&&!windowOpen" class="notice warning">目前時間窗尚未開放、已結束或尚未核對，不能新增入場；未使用票仍可撤銷。</p><button v-if="selected.state==='ACTIVE'" class="primary" :disabled="blocked||!enabled||!selected.eligible||!windowOpen||inspected?.id!==selected.id||inspected?.code!==code.trim()" @click="perform('CHECK_IN')">確認驗票入場</button><label v-if="selected.state==='ACTIVE'">撤銷原因<select v-model="reason" :disabled="blocked"><option value="LOST_CODE">票券碼遺失</option><option value="SECURITY">安全核對</option><option value="OPERATION_ERROR">作業錯誤</option></select></label><button v-if="selected.state==='ACTIVE'" :disabled="blocked||!enabled" @click="perform('REVOKE')">撤銷未使用票券</button><p v-for="a in audit?.items" :key="a.requestId" class="muted">{{a.action==='CHECK_IN'?'驗票':'撤銷'}} · {{state(a.state)}} · 原操作 {{a.requestId}}</p></article><section v-if="list" class="panel"><h2>場次票券</h2><button v-for="t in list.items" :key="t.id" class="event-select" @click="selected=t;code='';inspected=null;readAudit()">{{t.ticketName}} · 第 {{t.unit}} 張 · {{state(t.state)}}</button><p class="muted">清單不顯示票券碼；驗票請先輸入持票人的票券碼核對。</p><div class="pagination"><button :disabled="page===1||loading" @click="page--;load()">上一頁</button><span>{{page}} · {{list.total}} 張</span><button :disabled="page*list.size>=list.total||loading" @click="page++;load()">下一頁</button></div></section></section></template>
